package com.boutique.order.dto; import com.boutique.order.entity.*;import java.math.BigDecimal;import java.time.Instant;import java.util.*; public record OrderResponse(UUID id,String status,BigDecimal total,String currency,UUID paymentId,UUID userId,Instant createdAt,List<Item> items){public record Item(UUID productId,String sku,String name,BigDecimal unitPrice,int quantity,BigDecimal lineTotal){} public static OrderResponse from(OrderEntity o){return new OrderResponse(o.getId(),o.getStatus().name(),o.getTotal(),o.getCurrency(),o.getPaymentId(),o.getUserId(),o.getCreatedAt(),o.getItems().stream().map(i->new Item(i.getProductId(),i.getSku(),i.getName(),i.getUnitPrice(),i.getQuantity(),i.getLineTotal())).toList());}}
